SET search_path TO new_design, public;

CREATE TEMP TABLE xianxia_demo_cards (
  id uuid PRIMARY KEY,
  version_id uuid NOT NULL,
  card_type_key text NOT NULL,
  title text NOT NULL,
  values jsonb NOT NULL
) ON COMMIT DROP;

INSERT INTO xianxia_demo_cards (id, version_id, card_type_key, title, values) VALUES
('22000000-0000-4000-8000-000000000001', '23000000-0000-4000-8000-000000000001', 'theme', '《照骨山河》主题：谁来记住代价', $json${"proposition":"真相不能只由一个愿意牺牲的人保存；只有让证据、责任和决定被共同承担，秩序才不会把个人抹成必要代价。","counterargument":"灾难面前必须由少数人承担代价，公开全部真相只会让更多人恐慌并破坏唯一可行的秩序。","carriers":"沈照微代表共同见证；陆归尘代表程序秩序；闻无赦代表以更大破坏终止旧牺牲；谢停云代表沉默造成的共犯责任。","proof_events":"无灯观互记真名、母镜全网广播、白水互保会共同疏散、枯星井前拒绝单人献祭。","ending_answer":"共同承担仍然会痛苦且低效，但能让代价被看见、被轮换、被追责，比把牺牲包装成天命更接近可持续的秩序。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000002', '23000000-0000-4000-8000-000000000002', 'plotline', '《照骨山河》主线：照骨灯与父亲旧案', $json${"name":"照骨灯与父亲旧案","purpose":"推动沈照微从为父洗罪的私人目标，走向揭开镇劫阵献祭制度并重建守阵方式的公共选择。","participants":"沈照微、谢停云、陆归尘、闻无赦、悬镜司、清微山","opening":"逆水殓舟带回十年前劫纹，照骨灯自行点燃并显示沈砚舟登船残影。","development":"追查第七人和母镜碎片；进入无灯观建立外部记忆锚；在云津渡取得旧河道路权；用母镜恢复被删命令。","climax":"枯星井真假两门同时开启，沈照微以记忆点灯，陆归尘广播旧案，众人拒绝再次指定一个守灯人承担全部回流。","resolution":"白水驿获救，旧案公开但闻无赦带走活化星骸；沈照微成为临时守灯人并继续追查十二阵眼。","status":"active"}$json$::jsonb),
('22000000-0000-4000-8000-000000000003', '23000000-0000-4000-8000-000000000003', 'world_rule', '《照骨山河》世界规则：九州镇劫体系', $json${"era":"架空王朝景和末年，灵脉衰退后的第七十六年","world_summary":"九州山河由十二座镇劫大阵稳定，仙门负责看守阵眼，朝廷悬镜司负责征调灵材与登记修士。灵气并未消失，而是被旧阵集中抽取，外围乡镇因此频发旱灾、兽变和失踪。照骨岭是废弃阵眼之一，十年前发生星骸坠落，官方以山火封案。","geography":"主线从白水河谷展开，经云津渡、白水驿进入照骨岭；山中分布无灯观、清微山外院和枯星井。更远处十二阵眼沿古河道相连，第一部只展示西南三阵。","society":"凡人依附驿路、宗族和商会生存；登记修士享有通行、持器与征税特权。仙门弟子分外院、内门、真传三级，悬镜司能以劫灾名义接管地方。散修通过渡牒合法流动，黑市则交易记忆、寿元和阵图。","culture":"百姓在门楣悬白石避劫，送行时赠一盏不点燃的空灯，表示愿对方记得归路。修士重誓名与师承，直呼旧名被视为追索因果。","power_rules":"修行分听息、引脉、照神、结丹、化境五阶。术法必须借自身经脉与地脉共振；越级调用会留下可被照骨术看见的裂痕。法器存有历任使用者的因果回声，强行驱动会反噬记忆或寿元。","hard_rules":"死亡不能常规逆转；记忆一旦被照骨灯燃尽只能通过他人保存的证据重建，不能原样恢复；传送依赖阵门且受地脉状态限制；任何镇劫阵都必须有活人承担回流代价。"}$json$::jsonb),

('22000000-0000-4000-8000-000000000004', '23000000-0000-4000-8000-000000000004', 'character', '《照骨山河》沈照微', $json${"name":"沈照微","aliases":"阿微、提灯人","story_role":"protagonist","identity":"白水驿验伤学徒，罪修遗孤","age":17,"appearance":"身形单薄，右眼下有一道浅银胎记；常穿便于行路的灰蓝短袄，腰间挂着一串无字木牌。","language_habit":"遇到害怕的事会先问具体步骤；判断别人说谎时反而变得很客气。","signature_action":"思考时用拇指摩挲木牌边缘，点灯前会依次确认出口、同伴和代价。","personality":"观察细、韧性强，不轻信权威；习惯独自承担，容易把求助误解为软弱。","goal":"查明父亲旧案并阻止照骨岭劫脉爆发。","desire":"证明一个人的出身不能决定他的罪名，也希望自己能有一处无需随时离开的家。","fear":"最怕灯火夺走她对父亲和养母的记忆，最终只剩任务而不再像一个人。","secret":"她幼时已经点过一次照骨灯，忘记了星骸坠落当夜真正救她的人。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000005', '23000000-0000-4000-8000-000000000005', 'character', '《照骨山河》谢停云', $json${"name":"谢停云","aliases":"谢先生、无灯客","story_role":"mentor","identity":"无灯观最后一任守观人，前清微山阵师","age":46,"appearance":"旧白袍洗得发灰，左手两指焦黑，随身背一只没有琴弦的木匣。","language_habit":"从不直接说应该怎么做，总让人先报出愿意承担的代价。","signature_action":"听见谎话时会把木匣向左挪半寸。","personality":"克制、耐心、背负强烈愧疚；愿救具体的人，却不再相信宏大名义。","goal":"在枯星井开启前找到无需献祭守灯人的替代阵式。","desire":"让当年因自己沉默而被定罪的沈砚舟得到公正。","fear":"再次为了多数人的安全默认牺牲少数人。","secret":"十年前他参与修改照骨阵，沈砚舟替他带走了能证明献祭制度的母镜碎片。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000006', '23000000-0000-4000-8000-000000000006', 'character', '《照骨山河》陆归尘', $json${"name":"陆归尘","aliases":"陆少监","story_role":"opponent","identity":"悬镜司少年巡检，阵亡修士家族继承人","age":19,"appearance":"玄色窄袖制服一尘不染，佩一面裂纹铜镜，走路总比同行人快半步。","language_habit":"说话喜欢引用条例编号，真正动怒时会省略所有称谓。","signature_action":"进屋先看窗、门和屋梁，再看人。","personality":"守序、敏锐、自律，能够承认事实却很难承认制度错误。","goal":"追回照骨灯并按期限封锁照骨岭，避免劫气外泄。","desire":"证明父兄的牺牲维护了真实的秩序，而非一场被粉饰的错误。","fear":"发现自己一生遵守的律令建立在活人献祭上。","secret":"他佩戴的铜镜中保存着沈照微幼年点灯的影像，但被司内封印遮去关键一刻。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000007', '23000000-0000-4000-8000-000000000007', 'character', '《照骨山河》孟青萝', $json${"name":"孟青萝","aliases":"青萝、孟药娘","story_role":"supporting","identity":"白水驿药铺继承人，未登记的听息境修士","age":18,"appearance":"总把袖口扎得很紧，发间插一支量药银簪，手背留有常年试药的淡青斑。","language_habit":"先报最坏结果，再补一句可行办法；骂人时使用药名。","signature_action":"紧张时会数对方呼吸，借此判断伤势和情绪。","personality":"现实、嘴硬、重情，擅长在资源不足时做取舍。","goal":"找到治愈母亲劫纹病的方法，并保住白水驿不被封镇。","desire":"让凡人的医术不再只是修士术法的附庸。","fear":"为了救至亲而成为自己最厌恶的黑市试药人。","secret":"她母亲的病并非感染，而是十年前替沈照微承受了一部分灯火反噬。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000008', '23000000-0000-4000-8000-000000000008', 'character', '《照骨山河》裴观星', $json${"name":"裴观星","aliases":"裴掌柜、观星客","story_role":"supporting","identity":"云津渡船行掌柜，前渡厄盟引路人","age":34,"appearance":"笑眼、圆脸，右腿装有木铁混制的机关义肢，衣襟永远夹着三张不同颜色的船票。","language_habit":"把危险说成生意，把承诺说成价钱；真正关心时只说短句。","signature_action":"谈判前会把三张船票依风险从低到高排开。","personality":"圆滑、胆大、讲实际信用，不愿再为任何阵营效死。","goal":"护送沈照微穿过封锁线，以此换回被渡厄盟扣住的女儿。","desire":"攒够赎金后开一条不需要修士许可的民船线。","fear":"再一次因为算计活路而把同行者送进死局。","secret":"他知道一条通往枯星井的旧河道，但每次通行都会唤醒水下星骸。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000009', '23000000-0000-4000-8000-000000000009', 'character', '《照骨山河》闻无赦', $json${"name":"闻无赦","aliases":"渡主、白面道人","story_role":"antagonist","identity":"渡厄盟盟主，前悬镜司阵务官","age":52,"appearance":"面色苍白近乎透明，颈侧有一圈旧阵锁痕，手持一柄没有刃的黑伞。","language_habit":"从不否认自己做过的事，只争辩谁有资格定义代价。","signature_action":"每次提出交易都会先主动交出一项真实情报。","personality":"冷静、有说服力、相信目的高于个体；对被制度牺牲者有真切同情，却把同情变成新的强迫。","goal":"打开枯星井，切断十二镇劫阵对外围地脉的抽取。","desire":"结束守灯人世代献祭，即使必须让现有王朝和仙门一同崩塌。","fear":"发现仍有温和解法，从而证明自己造成的死亡并非必要。","secret":"他并不能控制井中星骸，只能借沈照微的灯暂时引导；开井后最先毁灭的正是白水河谷。"}$json$::jsonb),

('22000000-0000-4000-8000-000000000010', '23000000-0000-4000-8000-000000000010', 'location', '《照骨山河》白水驿', $json${"name":"白水驿","location_type":"city","appearance":"沿旧驿道展开的河谷小镇，白墙被潮气染出灰纹，家家门楣悬着一块避劫白石。","atmosphere":"白天是商旅喧闹，入夜后所有灯火都蒙一层青纱，人们害怕光招来山中的东西。","story_function":"主角的日常世界与必须保护的具体家园；第一卷危机倒计时的承压点。","risk":"劫雨来临时旧伤会在活物身上重新裂开，镇民又被悬镜司封锁无法撤离。","access_rule":"官道通行需悬镜司路引；雨夜只有熟悉废盐道的人能绕过关卡。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000011', '23000000-0000-4000-8000-000000000011', 'location', '《照骨山河》照骨岭', $json${"name":"照骨岭","location_type":"wild","appearance":"山体像被巨刃纵向劈开，雨后岩壁浮出骨白纹路，林中常见朝同一方向弯折的树。","atmosphere":"越深入越安静，虫鸣会按固定次序消失，偶尔能听见并不存在的脚步回声。","story_function":"第一卷主要探索场，是旧案证据、修行试炼和地脉危机的交汇点。","risk":"照见术会把山体旧伤投射到使用者身上；迷路者会重复走过自己最想改写的一天。","access_rule":"每月朔日前后三日地脉平稳；其余时间需持归墟渡牒或由守观人引路。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000012', '23000000-0000-4000-8000-000000000012', 'location', '《照骨山河》无灯观', $json${"name":"无灯观","location_type":"building","appearance":"嵌在峭壁内的三进小观，所有灯台都被凿去灯盏，只剩中央石室保留一面空镜墙。","atmosphere":"清冷但有人生活的痕迹，厨房总温着粥，夜里镜墙会映出陌生人的背影。","story_function":"主角第一阶段的训练基地和团队据点，也是谢停云隐瞒旧案的压力空间。","risk":"观内禁火不是戒律，而是防止照骨灯与地下残阵共鸣。","access_rule":"入口只在日落后一刻显现；进入者必须说出一个愿意被同伴记住的真名。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000013', '23000000-0000-4000-8000-000000000013', 'location', '《照骨山河》云津渡', $json${"name":"云津渡","location_type":"city","appearance":"数十艘旧船首尾相接形成水上市镇，桥板随水位改变，最高处是一座改成票号的废塔。","atmosphere":"白日交易热闹，夜里船铃互相传递封锁和追捕消息。","story_function":"主角获得向导、第一次与敌方代理人谈判，并选择是否牺牲陌生人换取通行的地方。","risk":"渡厄盟控制暗河，悬镜司控制明面码头，任何身份都会被至少一方记录。","access_rule":"普通船票只到白水驿；黑色船票可进照骨岭，但持票人必须替船行完成一项委托。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000014', '23000000-0000-4000-8000-000000000014', 'location', '《照骨山河》枯星井', $json${"name":"枯星井","location_type":"wild","appearance":"并非水井，而是一条垂直贯穿山腹的黑色晶洞；井壁嵌着像星光一样缓慢移动的碎片。","atmosphere":"所有声音都会延迟返回，越靠近井底越容易听见自己遗忘的声音。","story_function":"第一卷高潮地点和全书核心谜团入口，连接星骸、旧阵与主角记忆代价。","risk":"井口开启会吸走周边地脉，强行封闭则需要活人承担劫气回流。","access_rule":"需照骨灯、母镜碎片和守阵者真名同时满足，缺一只能开启假门。"}$json$::jsonb),

('22000000-0000-4000-8000-000000000015', '23000000-0000-4000-8000-000000000015', 'organization', '《照骨山河》清微山', $json${"name":"清微山","faction_type":"religion","purpose":"维护西南三座镇劫阵、培养阵师，并保持仙门对劫灾解释权。","leader":"掌教顾长衡；外院事务由执事院负责。","resources":"三座阵眼、完整修行谱系、地方香火田和与悬镜司共享的修士名册。","internal_conflict":"年轻阵师要求公开代价记录，长老派认为真相会引发地方恐慌和阵法停摆。","external_stance":"表面配合悬镜司封山，私下派人寻找失踪的母镜碎片。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000016', '23000000-0000-4000-8000-000000000016', 'organization', '《照骨山河》悬镜司', $json${"name":"悬镜司","faction_type":"organization","purpose":"登记修士、处置劫灾、保护十二镇劫阵及相关机密。","leader":"西南巡按韩九章；陆归尘直接受阵务处调遣。","resources":"官方路引、封镇权、铜镜传讯网、三百巡检与历代灾情档案。","internal_conflict":"巡检负责救人但档案官优先保阵，前线逐渐怀疑被隐瞒了真实伤亡。","external_stance":"将渡厄盟列为邪修，对清微山既依赖又防范，对沈照微采取先控制后审查。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000017', '23000000-0000-4000-8000-000000000017', 'organization', '《照骨山河》渡厄盟', $json${"name":"渡厄盟","faction_type":"informal","purpose":"终止镇劫阵对外围乡镇和守灯人的持续献祭，重分九州灵脉。","leader":"闻无赦。","resources":"暗河航线、被除名修士、黑市灵材、部分旧阵图和能遮蔽铜镜追踪的黑伞。","internal_conflict":"救乡派主张先疏散再破阵，开井派认为拖延只会让仙门补强旧秩序。","external_stance":"招募灾民并袭击押运队；愿与沈照微交易，但把她视为开启枯星井的必要钥匙。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000018', '23000000-0000-4000-8000-000000000018', 'organization', '《照骨山河》白水互保会', $json${"name":"白水互保会","faction_type":"organization","purpose":"在官府封锁和劫灾期间维持粮药、撤离顺序与孤弱照料。","leader":"由药铺、船行、驿卒和三位里正轮值，无固定首领。","resources":"废盐道、镇民名册、粮仓钥匙、民间医者和跨村铜锣信号。","internal_conflict":"一派相信悬镜司会救援，一派准备强行突围；两派都害怕先公开灾情会引发抢粮。","external_stance":"不公开支持任何修士阵营，只接受能直接降低镇民伤亡的合作。"}$json$::jsonb),

('22000000-0000-4000-8000-000000000019', '23000000-0000-4000-8000-000000000019', 'prop', '《照骨山河》照骨灯', $json${"name":"照骨灯","prop_type":"treasure","appearance":"一盏巴掌大的乌铜提灯，没有灯芯，内壁遍布细小人名，点燃时呈无影白焰。","origin":"由第一代守灯人以星骸外壳铸成，历代用来检查镇劫阵裂痕。","ability":"照出人、物和地脉承受过的旧伤及因果残影，可短暂让隐藏阵纹显形。","limit":"每次使用必须燃烧持灯者一段真实记忆；照见越久远、越宏大的伤，失去的记忆越重要。","prop_status":"available"}$json$::jsonb),
('22000000-0000-4000-8000-000000000020', '23000000-0000-4000-8000-000000000020', 'prop', '《照骨山河》断纹母镜', $json${"name":"断纹母镜","prop_type":"document","appearance":"三角形铜镜碎片，背面刻半幅河道，裂边会在月下渗出细蓝光。","origin":"悬镜司照影档案的母镜，被沈砚舟从十年前事故现场带走。","ability":"与巡检铜镜相合时可恢复被删改的影像和命令记录。","limit":"只能重现一次完整记录，之后镜面会永久雾化；需要两名立场相反的见证者同时持镜。","prop_status":"sealed"}$json$::jsonb),
('22000000-0000-4000-8000-000000000021', '23000000-0000-4000-8000-000000000021', 'prop', '《照骨山河》七窍剑丸', $json${"name":"七窍剑丸","prop_type":"weapon","appearance":"七枚米粒大小的灰银丸，平时藏在银簪中，以呼吸节奏控制。","origin":"孟家祖传外科针具被孟青萝改造成护身法器。","ability":"可封穴止血、切断细小阵线，也能在三丈内组成一次防御剑网。","limit":"使用者必须持续感知七枚剑丸，分心就会误伤；一日最多完整结网两次。","prop_status":"available"}$json$::jsonb),
('22000000-0000-4000-8000-000000000022', '23000000-0000-4000-8000-000000000022', 'prop', '《照骨山河》归墟渡牒', $json${"name":"归墟渡牒","prop_type":"document","appearance":"黑底船票，水浸后会显出一条随月相变化的银色河道。","origin":"旧阵维护船队使用的通行凭证，现由云津渡黑市流通。","ability":"让持有人在照骨岭迷障中看见一次最近的安全路径。","limit":"每张只能使用一次，且路径只保证当时可通，不保证终点安全。","prop_status":"available"}$json$::jsonb),

('22000000-0000-4000-8000-000000000023', '23000000-0000-4000-8000-000000000023', 'event', '《照骨山河》十年前星骸坠岭', $json${"name":"十年前星骸坠岭","story_time":"景和十二年秋","summary":"天外星骸坠入照骨岭，旧阵出现不可逆裂口。沈砚舟、谢停云和闻无赦参与处置，悬镜司最终以山火事故封存记录。","cause":"十二镇劫阵长期抽取灵脉，使阵外星骸被地脉空洞吸引坠落。","process":"处置队发现必须献祭守灯人才能维持旧阵；沈砚舟带走证据并救出幼年沈照微。","result":"沈砚舟被定为叛逃邪修，闻无赦出走建立渡厄盟，谢停云隐居无灯观，沈照微失去当夜记忆。","importance":"turning_point","event_status":"completed"}$json$::jsonb),
('22000000-0000-4000-8000-000000000024', '23000000-0000-4000-8000-000000000024', 'event', '《照骨山河》殓舟夜泊白水驿', $json${"name":"殓舟夜泊白水驿","story_time":"第一章，景和二十二年七月十三日夜","summary":"一艘无人殓舟逆流停在白水驿，船中死者都带着十年前才会出现的劫纹，沈照微验伤时听见灯中有人叫她旧名。","cause":"渡厄盟用殓舟运送从旧阵剥离的劫气，途中被悬镜司截断引路术。","process":"沈照微与孟青萝查验尸身，陆归尘封锁码头，照骨灯因尸体携带的母镜气息自行点燃。","result":"沈照微失去一段母亲做饭的记忆，却看见父亲曾登上同一艘船；悬镜司认出灯火并开始追捕。","importance":"major","event_status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000025', '23000000-0000-4000-8000-000000000025', 'event', '《照骨山河》白水封镇', $json${"name":"白水封镇","story_time":"第二至三章","summary":"悬镜司以防止劫病扩散为由封闭白水驿，镇民药粮只能维持五日，山雨将在第三日提前到来。","cause":"殓舟劫纹与照骨灯同时出现，巡按担心十年前事故真相泄露。","process":"陆归尘执行封锁，互保会准备突围，渡厄盟散布开井可救全镇的消息。","result":"沈照微决定离镇入岭寻找阵眼，孟青萝为母亲药方同行，二人与陆归尘形成临时追逃关系。","importance":"major","event_status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000026', '23000000-0000-4000-8000-000000000026', 'event', '《照骨山河》无灯观试心', $json${"name":"无灯观试心","story_time":"第四至第五章","summary":"沈照微进入无灯观学习不点灯也能辨认地脉伤痕的听息法，并在镜墙前选择公开自己会遗忘的事实。","cause":"谢停云拒绝把照骨灯交给只想复仇或求证的人，要求她先建立不依赖个人记忆的证据链。","process":"团队互相记录真名、目标和底线；沈照微发现自己的木牌能补全镜墙缺失的人名。","result":"她完成听息入门，获得谢停云有限协助，也意识到导师参与了父亲旧案。","importance":"turning_point","event_status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000027', '23000000-0000-4000-8000-000000000027', 'event', '《照骨山河》云津渡换票', $json${"name":"云津渡换票","story_time":"第六章","summary":"沈照微必须在交出照骨灯、救出一船被扣灾民和继续追父亲线索之间做选择，最终用公开一段镜像证据换取黑船票。","cause":"裴观星掌握入岭路线但女儿被渡厄盟控制，双方都拿人质逼他选边。","process":"沈照微与陆归尘短暂合作制造两份真假难辨的押运记录，孟青萝切断追踪阵线。","result":"灾民获救，裴观星加入队伍，闻无赦确认沈照微已经能主动使用灯。","importance":"major","event_status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000028', '23000000-0000-4000-8000-000000000028', 'event', '《照骨山河》枯星井初开', $json${"name":"枯星井初开","story_time":"第八章末至第十章","summary":"渡厄盟抢先拼合假门，导致劫气倒灌白水河谷。沈照微必须决定是否燃烧关于父亲的核心记忆来照出真正封井结构。","cause":"闻无赦误判自己已掌握星骸，悬镜司又试图强行补阵，双方动作叠加撕裂井口。","process":"团队分为井下找阵心、地面疏散与公开旧案三线；陆归尘以母镜向巡检网广播被删命令。","result":"第一卷危机暂时封住，献祭制度曝光，闻无赦带走一块活化星骸；沈照微保住父亲面容，却忘记父亲的声音。","importance":"turning_point","event_status":"planned"}$json$::jsonb),

('22000000-0000-4000-8000-000000000029', '23000000-0000-4000-8000-000000000029', 'world_rule', '《照骨山河》世界规则：时间与行程', $json${"era":"景和二十二年；十二月历法，以朔望标记照骨岭地脉强弱。","world_summary":"故事第一卷连续覆盖十天。白水驿用更鼓计夜，船行用潮刻计航程；每次旅行、修炼和记忆损失都要在章节卡中留下可核对的时间结果。","geography":"白水驿到云津渡顺流半日、逆流一日；云津渡到无灯观步行两日；无灯观到枯星井正常一日，劫雨中行程翻倍。","society":"悬镜司以路引和封镇令控制跨地移动，民间船行与互保会掌握更快但风险更高的暗路。","culture":"朔日前后三日适合入山，望日前后劫气最强；地方居民会在门楣记录家人最后一次清醒的日期。","power_rules":"照骨灯造成的记忆缺失立即生效，不能延迟支付，也不能通过章节跳时规避。","hard_rules":"主线顺叙；旧案残影只能由道具或地点触发，每次不超过一个场景，并且只给当前人物能够误读的有限信息。"}$json$::jsonb),

('22000000-0000-4000-8000-000000000030', '23000000-0000-4000-8000-000000000030', 'foreshadow', '《照骨山河》伏笔：无字木牌', $json${"name":"无字木牌","setup_content":"沈照微腰间木牌看似没有文字，靠近无灯观镜墙时却补全一个被凿去的守灯人名字。","planted_at":"第一章验伤时，木牌先于照骨灯发热","reader_visibility":"subtle","payoff_plan":"第五章揭示它是父亲留下的记忆锚；第十章用于替沈照微保存一句不能被灯火夺走的自我约定。","status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000031', '23000000-0000-4000-8000-000000000031', 'clue_evidence', '《照骨山河》线索：殓舟第七具空棺', $json${"name":"殓舟第七具空棺","content":"船册登记七人，船上只有六具尸体，第七口棺内留有刚干的白水与一根巡检制服纤维。","points_to":"第七人曾进入船舱并带走母镜碎片，且与悬镜司巡检系统有关。","source":"第一章码头验船","reliability":"verified","discovered_at":"第一章场景2","status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000032', '23000000-0000-4000-8000-000000000032', 'clue_evidence', '《照骨山河》线索：母亲药方缺页', $json${"name":"母亲药方缺页","content":"孟青萝母亲的劫纹药方总从第二味药开始，第一页被整齐割走，残页边缘与沈照微木牌宽度一致。","points_to":"孟母曾参与替幼年沈照微分担照骨灯反噬的仪式。","source":"第二章孟家药铺","reliability":"questionable","discovered_at":"第二章","status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000033', '23000000-0000-4000-8000-000000000033', 'clue_evidence', '《照骨山河》线索：陆归尘镜中缺帧', $json${"name":"陆归尘镜中缺帧","content":"陆归尘的铜镜每次回放十年前记录都会在同一息变暗，他以为是镜裂，沈照微却看见裂纹上有新刻阵线。","points_to":"旧案记录被悬镜司内部人为删改，母镜碎片可恢复原始影像。","source":"第三章第一次对质","reliability":"verified","discovered_at":"第三章","status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000034', '23000000-0000-4000-8000-000000000034', 'foreshadow', '《照骨山河》伏笔：闻无赦的真情报', $json${"name":"闻无赦的真情报","setup_content":"闻无赦每次交易都先交出真实情报，使众人逐渐把真实等同于善意，但他刻意只给能迫使对方行动的那部分真相。","planted_at":"第四章黑伞信使送来封镇时限","reader_visibility":"subtle","payoff_plan":"第九章揭示开井会先毁白水河谷；此前所有情报都是真的，却被排列成唯一可接受开井的叙事。","status":"planned"}$json$::jsonb),
('22000000-0000-4000-8000-000000000035', '23000000-0000-4000-8000-000000000035', 'foreshadow', '《照骨山河》伏笔：忘记的父亲声音', $json${"name":"忘记的父亲声音","setup_content":"沈照微能描述父亲的面容和动作，却从第一章起无法在心中复现他的声音，说明她曾为更重要的照见支付过代价。","planted_at":"第一章灯中有人叫她幼年旧名，她无法判断是否像父亲","reader_visibility":"obvious","payoff_plan":"第十章回收：十年前她主动点灯看见献祭名单，父亲让她选择忘记声音而不是忘记真相；卷末再次失去声音形成有意识的重复选择。","status":"planned"}$json$::jsonb),

('22000000-0000-4000-8000-000000000036', '23000000-0000-4000-8000-000000000036', 'volume_plan', '《照骨山河》第一卷：无灯照夜', $json${"volume_name":"第一卷：无灯照夜","theme":"看见真相不等于拥有真相；只有让证据被多人保存，个人记忆的牺牲才不会再次被权力抹去。","opening_state":"沈照微在白水驿以验伤手艺谋生，只想低调查找父亲线索；她没有正式修为，也不信任仙门与官府。","major_goal":"十天内阻止枯星井劫气倒灌白水河谷，并取得能公开父亲旧案的完整镜像证据。","midpoint_turn":"无灯观试心后，沈照微发现谢停云也是旧案参与者；她从寻找一个无罪证明转为调查整个献祭制度。","climax":"枯星井真假两门同时开启，沈照微必须以记忆点灯、陆归尘必须违抗直属命令、孟青萝必须放弃只救母亲的药方，三人共同完成封井与公开证据。","ending_state":"白水驿获救，悬镜司和清微山出现公开分裂；沈照微进入听息境并成为临时守灯人，闻无赦带走活化星骸，下一卷指向第二座阵眼。"}$json$::jsonb),

('22000000-0000-4000-8000-000000000037', '23000000-0000-4000-8000-000000000037', 'chapter_plan', '《照骨山河》第1章：逆水殓舟', $json${"chapter_name":"第1章：逆水殓舟","chapter_number":1,"chapter_goal":"让沈照微在一次具体验伤中发现十年前旧案重新出现，并因照骨灯意外点燃失去第一段记忆。","conflict":"陆归尘要求封船封口，孟青萝急需确认尸体是否携带会伤及镇民的劫病，沈照微既怕暴露身份又不能放任风险。","participants":"沈照微、孟青萝、陆归尘；死者与船夫只作为现场证据出现。","location":"白水驿码头与验伤棚","must_reveal":"照骨灯能看见旧伤但会吞记忆；十年前沈砚舟押送过同一艘船；船册有第七人而船上只有六具尸体。","foreshadow_action":"埋设无字木牌发热、父亲声音缺失、空棺制服纤维三条线索。","ending_hook":"陆归尘在白焰中认出沈照微，并下令关闭全镇出口。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000038', '23000000-0000-4000-8000-000000000038', 'chapter_plan', '《照骨山河》第2章：青纱封灯', $json${"chapter_name":"第2章：青纱封灯","chapter_number":2,"chapter_goal":"建立白水驿五日粮药倒计时，让沈照微决定不能只躲避追查。","conflict":"悬镜司禁止接触尸体，互保会却需要病因；孟青萝要求沈照微再次点灯救母亲，沈照微拒绝无准备支付记忆。","participants":"沈照微、孟青萝、陆归尘、孟母、互保会里正","location":"孟家药铺与封锁街口","must_reveal":"镇民劫纹来自地脉而非传染；孟母替某人承担过灯火反噬；山雨将在三日后提前。","foreshadow_action":"展示药方缺页与木牌同宽，强化母亲线。","ending_hook":"第一滴劫雨落下时，全镇旧伤同时渗血。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000039', '23000000-0000-4000-8000-000000000039', 'chapter_plan', '《照骨山河》第3章：镜中缺一息', $json${"chapter_name":"第3章：镜中缺一息","chapter_number":3,"chapter_goal":"让沈照微和陆归尘从单纯追逃转为各持一半证据的对手。","conflict":"沈照微想查第七人，陆归尘必须在上级到达前追回灯；二人都发现对方掌握自己需要的信息。","participants":"沈照微、陆归尘、孟青萝、第七人留下的追踪傀儡","location":"废盐道关卡","must_reveal":"铜镜记录被人为删去一息；第七人带着母镜碎片进入照骨岭；陆归尘也不知道完整旧案。","foreshadow_action":"埋设裂纹上的新刻阵线，第一次展示渡厄盟黑伞标记。","ending_hook":"谢停云隔着雨幕叫出沈照微幼年使用的真名。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000040', '23000000-0000-4000-8000-000000000040', 'chapter_plan', '《照骨山河》第4章：无灯观门', $json${"chapter_name":"第4章：无灯观门","chapter_number":4,"chapter_goal":"把团队带入训练据点，并明确进入照骨岭必须先学会不依赖灯的听息法。","conflict":"沈照微只想问父亲下落，谢停云拒绝回答；陆归尘追到观外却无法说出愿被记住的真名。","participants":"沈照微、孟青萝、谢停云、陆归尘","location":"无灯观入口与厨房","must_reveal":"谢停云认识父亲并参与旧案；观内禁火是为了防止地下残阵共鸣；修行第一步是感知代价而非操纵力量。","foreshadow_action":"木牌在镜墙前显出半个名字；闻无赦送来一条内容完全真实的警告。","ending_hook":"镜墙映出沈照微身后站着一个只有她看不见的幼年自己。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000041', '23000000-0000-4000-8000-000000000041', 'chapter_plan', '《照骨山河》第5章：先记住我', $json${"chapter_name":"第5章：先记住我","chapter_number":5,"chapter_goal":"完成主角听息入门，并建立团队共同保存记忆和证据的合作规则。","conflict":"试心要求每人公开一个可能被利用的秘密；沈照微认为谢停云无权要求信任，孟青萝也隐瞒母亲替人承伤。","participants":"沈照微、孟青萝、谢停云、陆归尘","location":"无灯观镜室","must_reveal":"记忆可由文字、物证和他人证词建立外部锚点；沈砚舟曾要求谢停云不要把女儿培养成一次性钥匙。","foreshadow_action":"回收木牌第一层用途，强化谢停云的木匣与母镜有关。","ending_hook":"沈照微在不点灯的情况下听见整座山像伤者一样呼吸。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000042', '23000000-0000-4000-8000-000000000042', 'chapter_plan', '《照骨山河》第6章：三张船票', $json${"chapter_name":"第6章：三张船票","chapter_number":6,"chapter_goal":"取得进入枯星井的路线和向导，同时让团队第一次主动赢下一场信息博弈。","conflict":"裴观星必须用沈照微换女儿，渡厄盟扣住灾民逼他交人，悬镜司则封死明面码头。","participants":"沈照微、孟青萝、陆归尘、裴观星、渡厄盟信使","location":"云津渡水上市镇","must_reveal":"黑票路线会经过水下星骸；闻无赦掌握开井方法但缺少真正钥匙；药方缺页记录了分担反噬。","foreshadow_action":"回收药方缺页，强化闻无赦用真相操纵选择的模式。","ending_hook":"获救灾民中有人醒来，称沈照微为十年前的守灯人。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000043', '23000000-0000-4000-8000-000000000043', 'chapter_plan', '《照骨山河》第7章：旧河道', $json${"chapter_name":"第7章：旧河道","chapter_number":7,"chapter_goal":"让队伍穿过第一段高风险秘境，取得母镜碎片并确认官方清除见证的命令。","conflict":"旧河道会放大每个人最想改写的过去；陆归尘必须在救直属同僚和保住证据之间选择。","participants":"沈照微、陆归尘、孟青萝、裴观星、第七人","location":"照骨岭旧河道","must_reveal":"第七人是悬镜司档案官；沈照微十年前主动点过灯；陆归尘上级正在准备以白水驿为新阵祭。","foreshadow_action":"母镜碎片与铜镜第一次共鸣但暂不播放完整影像。","ending_hook":"枯星井方向升起一轮只有修士能看见的黑月。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000044', '23000000-0000-4000-8000-000000000044', 'chapter_plan', '《照骨山河》第8章：真相只亮一次', $json${"chapter_name":"第8章：真相只亮一次","chapter_number":8,"chapter_goal":"公开十年前的关键命令，使陆归尘正式违抗上级，并把故事推入封井高潮。","conflict":"母镜完整回放只有一次；若只给队伍看可保留战术优势，若向巡检网广播则会暴露位置并加速敌人开井。","participants":"沈照微、陆归尘、孟青萝、谢停云、裴观星、韩九章的镜像","location":"枯星井上层阵台","must_reveal":"沈砚舟不是偷走星骸，而是阻止悬镜司献祭幼年沈照微；谢停云曾签署沉默令；闻无赦隐瞒了开井先毁白水的后果。","foreshadow_action":"回收镜中缺帧与真情报误导，留下父亲声音为何已失的最后谜面。","ending_hook":"广播完成后，假门和真门同时裂开，白水河开始倒流。"}$json$::jsonb),

('22000000-0000-4000-8000-000000000045', '23000000-0000-4000-8000-000000000045', 'scene_plan', '《照骨山河》第1章场景1：殓舟靠岸', $json${"scene_name":"第1章场景1：殓舟靠岸","order_number":1,"pov":"沈照微","location":"白水驿码头","objective":"在不惊动镇民的情况下确认逆水而来的殓舟是否载有疫病。","obstacle":"船无活人操控却精准停靠，陆归尘的人正在赶来，围观者已经认出沈照微的验伤身份。","turn":"沈照微发现六具尸体的鞋底都沾着照骨岭才有的白砂，而船册登记七人。","exit_state":"她决定先封码头不封消息，派孟青萝取验伤工具；读者得到异常、主角职业和倒计时。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000046', '23000000-0000-4000-8000-000000000046', 'scene_plan', '《照骨山河》第1章场景2：第七口棺', $json${"scene_name":"第1章场景2：第七口棺","order_number":2,"pov":"沈照微","location":"殓舟舱内","objective":"找出第七人的去向，并判断死者劫纹出现的先后顺序。","obstacle":"舱门有官封但封泥日期晚于死亡时间；孟青萝担心母亲病症与尸纹相同，情绪影响判断。","turn":"空棺中没有尸体，只有一根巡检制服纤维和未干的白水。","exit_state":"两人确认这不是普通运尸，而是有人借尸体运送会活动的劫气。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000047', '23000000-0000-4000-8000-000000000047', 'scene_plan', '《照骨山河》第1章场景3：巡检封船', $json${"scene_name":"第1章场景3：巡检封船","order_number":3,"pov":"沈照微","location":"验伤棚外","objective":"保住尸检记录并让陆归尘允许镇民采取防护措施。","obstacle":"陆归尘按条例要求焚船封口，沈照微一旦解释劫纹来源就会暴露父亲教过她照伤术。","turn":"陆归尘没有否认十年前也出现过相同纹路，反而追问她从哪里见过。","exit_state":"双方互相确认对方掌握旧案碎片，谈判破裂但都暂缓焚船。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000048', '23000000-0000-4000-8000-000000000048', 'scene_plan', '《照骨山河》第1章场景4：白焰照伤', $json${"scene_name":"第1章场景4：白焰照伤","order_number":4,"pov":"沈照微","location":"验伤棚","objective":"阻止一具尸体突然释放劫气伤及围观镇民。","obstacle":"常规药粉无效，唯一可用的照骨灯会暴露身份且支付未知记忆。","turn":"灯自行点燃，沈照微看见父亲十年前登上同一艘船，并看见尸体伤痕来自山体而非疾病。","exit_state":"劫气被压回尸体，她却再也想不起母亲做饭的味道；能力、代价和父亲线同时成立。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000049', '23000000-0000-4000-8000-000000000049', 'scene_plan', '《照骨山河》第1章场景5：旧名与封镇', $json${"scene_name":"第1章场景5：旧名与封镇","order_number":5,"pov":"沈照微","location":"白水驿码头街","objective":"带着灯和记录离开巡检控制范围。","obstacle":"陆归尘认出白焰，所有出口同时落闸；孟青萝要求她先说明失去了什么。","turn":"灯中传出一个男人叫她幼年旧名，她知道那可能是父亲，却发现自己无法回忆父亲的声音进行确认。","exit_state":"沈照微带孟青萝进入废盐道；陆归尘下令全镇封锁，章末形成追捕与记忆谜题双钩子。"}$json$::jsonb),

('22000000-0000-4000-8000-000000000050', '23000000-0000-4000-8000-000000000050', 'secret_truth', '《照骨山河》真相：十年前守灯人替换案', $json${"name":"十年前守灯人替换案","truth_content":"十年前悬镜司与清微山决定让幼年沈照微成为新守灯人。沈砚舟破坏仪式、带走母镜证据并承担叛逃罪名；孟母和谢停云分别分担反噬、签署沉默令。","known_by":"沈砚舟知道全貌；谢停云、孟母和韩九章各知道一部分；闻无赦知道制度目的但不知道沈照微主动点灯的最后选择。","hidden_from":"沈照微、陆归尘、白水驿镇民和普通巡检。","exposure_consequence":"陆归尘失去服从封镇令的正当性，谢停云必须承担沉默责任，沈照微的目标从为父洗罪转为终止单人献祭制度。","reveal_stage":"第一卷第八至十章","status":"hidden"}$json$::jsonb),
('22000000-0000-4000-8000-000000000051', '23000000-0000-4000-8000-000000000051', 'suspense_question', '《照骨山河》悬念：父亲当年到底做了什么', $json${"question":"沈砚舟十年前到底偷走了什么，又为什么让女儿忘记他的声音？","audience_knows":"官方称沈砚舟盗走星骸并引发山火；照骨灯残影却显示他在救人，母镜记录还被人为删去一息。","characters_know":"沈照微只记得父亲被定罪；陆归尘相信官方档案但发现铜镜有缺帧；谢停云知道献祭计划却不知沈砚舟与女儿最后的约定。","answer":"沈砚舟偷走的不是星骸，而是能证明活人献祭命令的母镜碎片；沈照微主动用父亲声音作为点灯代价，保住了献祭名单的记忆。","answer_deadline":"第一卷第十章","status":"open"}$json$::jsonb),
('22000000-0000-4000-8000-000000000052', '23000000-0000-4000-8000-000000000052', 'goal_task', '《照骨山河》目标：十日内封住枯星井', $json${"name":"十日内封住枯星井","owner":"沈照微与临时同行小队","desired_result":"在望日前阻止劫气倒灌白水河谷，同时取得并公开能证明十年前献祭命令的母镜记录。","motivation":"保住白水驿镇民、查清父亲旧案，并避免下一个孩子成为新的守灯祭品。","obstacle":"悬镜司封镇追捕、渡厄盟准备强行开井、队伍缺少母镜碎片和合法路权，照骨灯每次使用还会夺走记忆。","success_criteria":"白水河恢复顺流；枯星井重新封闭；镇民完成撤离或确认安全；旧案证据至少由三方独立保存。","status":"active"}$json$::jsonb),
('22000000-0000-4000-8000-000000000053', '23000000-0000-4000-8000-000000000053', 'conflict', '《照骨山河》冲突：公共安全与指定献祭', $json${"name":"公共安全与指定献祭","sides":"沈照微、白水互保会与年轻巡检主张共同承担和公开记录；悬镜司阵务处与清微山长老派坚持指定守灯人；渡厄盟则主张先摧毁旧阵。","conflict_core":"旧阵能快速维持大范围安全，却必须持续抹除少数人的记忆与人生；替代方案更公平但短期风险更高。","stakes":"维持旧制会牺牲沈照微并掩盖历史；立即毁阵会先摧毁白水河谷；拖延则枯星井在望日失控。","escalation":"从封船争执升级为封镇追捕、无灯观对质、母镜广播选择，最终在井口变成谁来承担回流的不可回避决定。","resolution_condition":"建立多人轮换、证据公开且能被地方共同监督的替代阵式，并让镇民拥有知情撤离权。","status":"escalated"}$json$::jsonb),
('22000000-0000-4000-8000-000000000054', '23000000-0000-4000-8000-000000000054', 'plot_beat', '《照骨山河》剧情节点：白焰认主', $json${"name":"白焰认主","structural_role":"inciting","intended_effect":"让读者同时确认主角的特殊能力、不可逆代价、父亲旧案和官方追捕四条推进力，迫使沈照微离开可维持的日常生活。","prerequisites":"先展示沈照微靠普通验伤手艺解决问题、殓舟异常和第七口空棺；读者需要理解她不愿暴露父亲所授技艺。","target_position":"第一卷第一章后半","fulfillment":"由场景4白焰照伤完成能力与代价，由场景5陆归尘认出白焰并封镇完成不可回头的外部行动。"}$json$::jsonb),
('22000000-0000-4000-8000-000000000055', '23000000-0000-4000-8000-000000000055', 'arc', '《照骨山河》弧线：沈照微从独自记住到共同见证', $json${"name":"从独自记住到共同见证","subject":"沈照微","start_state":"她把记住父亲、保存证据和承担灯火代价都视为自己的私人责任，不相信任何组织，也不愿让同伴分担风险。","pressure":"照骨灯不断夺走个人记忆；官方能删除单一档案；同伴因信息不对称反复做出相互冲突的选择。","turning_points":"第一章隐瞒代价导致孟青萝误判；第五章用木牌和互记真名建立外部锚点；第八章同意全网广播而非私藏母镜；第十章拒绝独自成为永久守灯人。","end_state":"她接受记忆可能无法完整保留，但要求真相由多人、物证和公开制度共同保存，并愿意成为可被监督和替换的临时守灯人。","status":"active"}$json$::jsonb);

INSERT INTO cards (
  id, space_id, card_type_id, title, status, revision,
  type_version_id, current_version_id, values
)
SELECT seed.id,
       '00000000-0000-4000-8000-000000000001',
       card_type.id,
       seed.title,
       'active',
       1,
       card_type.current_version_id,
       seed.version_id,
       seed.values
FROM xianxia_demo_cards seed
JOIN card_types card_type
  ON card_type.space_id = '00000000-0000-4000-8000-000000000001'
 AND card_type.type_key = CASE seed.card_type_key
       WHEN 'volume_plan' THEN 'volume'
       WHEN 'chapter_plan' THEN 'chapter'
       WHEN 'scene_plan' THEN 'scene'
       ELSE seed.card_type_key
     END
 AND card_type.current_version_id IS NOT NULL
ON CONFLICT (id) DO NOTHING;

INSERT INTO card_versions (
  id, card_id, revision, type_version_id, title, values, source
)
SELECT seed.version_id,
       seed.id,
       1,
       card.type_version_id,
       seed.title,
       seed.values,
       'create'
FROM xianxia_demo_cards seed
JOIN cards card ON card.id = seed.id
ON CONFLICT DO NOTHING;
